& {
    Set-ExecutionPolicy -Scope Process -ExecutionPolicy Bypass -Force
    $ExpectedSHA = "b73d77bc293ffa0a930c001c9958c94c9659648c20ad5ec582fc320fa0493423"
    $Target = Join-Path $env:USERPROFILE "Downloads\Invoke-VIA-Console-v0163.ps1"
    $B64 = ""
    try {
        $gz    = [System.Convert]::FromBase64String($B64)
        $msIn  = [System.IO.MemoryStream]::new($gz)
        $dec   = [System.IO.Compression.GZipStream]::new($msIn, [System.IO.Compression.CompressionMode]::Decompress)
        $msOut = [System.IO.MemoryStream]::new()
        $dec.CopyTo($msOut)
        $dec.Dispose()
        [System.IO.File]::WriteAllBytes($Target, $msOut.ToArray())
        $ActualSHA = (Get-FileHash -LiteralPath $Target -Algorithm SHA256).Hash.ToLowerInvariant()
        Write-Host ("def WROTE  : {0}" -f $Target) -ForegroundColor White
        Write-Host ("def SHA256 : {0}" -f $ActualSHA) -ForegroundColor DarkGray
        if ($ActualSHA -ne $ExpectedSHA) { Write-Host "def SHA256 FAIL — 已中止。" -ForegroundColor Red; return }
        Write-Host "def SHA256 : PASS" -ForegroundColor Green
        if ($PSVersionTable.PSVersion.Major -lt 7) {
            $Pwsh = ''
            $c = Get-Command pwsh.exe -ErrorAction SilentlyContinue
            if ($c) { $Pwsh = [string]$c.Source }
            if ([string]::IsNullOrWhiteSpace($Pwsh)) { Write-Host "def 需要 PowerShell 7 (pwsh)。" -ForegroundColor Red; return }
            Start-Process -FilePath $Pwsh -ArgumentList @("-NoLogo","-NoProfile","-ExecutionPolicy","Bypass","-NoExit","-File",('"{0}"' -f $Target))
            return
        }
        & $Target
    }
    catch { Write-Host ("def INSTALL SAFE CATCH : {0}" -f $_.Exception.Message) -ForegroundColor Red }
}

